from django.db import migrations, models
import django.db.models.deletion


def link_bots_to_tenants(apps, schema_editor):
    """把旧 Tenant.line_bot 关系转移到 LineBot.tenant(一个bot只属一个租户)"""
    Tenant = apps.get_model('tenant', 'Tenant')
    LineBot = apps.get_model('notify', 'LineBot')
    for tenant in Tenant.objects.all():
        bot_id = tenant.line_bot_id
        if not bot_id:
            continue
        LineBot.objects.filter(id=bot_id).update(tenant_id=tenant.id)


